import hashlib
from pathlib import Path

FOLDER = Path("my_folder")      # change this to your folder

def file_hash(path):
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):   # read in 1 MB pieces
            digest.update(chunk)
    return digest.hexdigest()

# 1. Group by size first: different sizes cannot be duplicates.
by_size = {}
for path in FOLDER.rglob("*"):
    if path.is_file():
        by_size.setdefault(path.stat().st_size, []).append(path)

# 2. Hash only the files that share a size.
groups = {}
for size, paths in by_size.items():
    if len(paths) > 1:
        for path in paths:
            groups.setdefault((size, file_hash(path)), []).append(path)

duplicates = [paths for paths in groups.values() if len(paths) > 1]
for paths in duplicates:
    print("Same content:")
    for path in paths:
        print("  ", path)

wasted = sum((len(paths) - 1) * paths[0].stat().st_size for paths in duplicates)
print(len(duplicates), "groups of duplicates,", wasted, "bytes could be saved.")

